def copiar_contacto_existente(apps, schema_editor):
    """Arranca con el correo y el celular que la empresa ya tenía en Qualitas o Seguros Mundial (y la dirección de
    Mundial), para que nada cambie al actualizar."""
    Credencial = apps.get_model('policies', 'AseguradoraCredencial')
    Contacto = apps.get_model('policies', 'ContactoPortales')
    if Contacto.objects.exists():
        return
    correo = celular = direccion = ''
    for c in Credencial.objects.filter(is_active=True).order_by('-id'):
        correo = correo or (c.correo_contacto or '').strip()
        celular = celular or (c.telefono_contacto or '').strip()
        direccion = direccion or str((c.parametros or {}).get('direccion') or '').strip()
    Contacto.objects.create(correo=correo[:100], celular=celular[:20], direccion=direccion[:150])


